import { mkdir, readFile, writeFile } from "fs/promises";
import { tmpdir } from "os";
import { join } from "path";

/**
 * Per-chat table that maps image labels to files.
 *
 * - attachments: a1, a2, ... images the user attached (rebuilt from the chat history every turn)
 * - variants:    v1, v2, ... images generated by ComfyUI (only ever appended, never renumbered)
 *
 * It is stored in LM Studio's per-chat working directory, so the generator (which builds the
 * conversation) and the generate_image tool (which runs ComfyUI) share the same table, and images
 * from different chats never mix.
 */
export type MediaState = {
  attachments: Record<string, string>;
  variants: Record<string, string>;
  /** Labels of the images attached to the user message that started the current turn. */
  turnAttachments: string[];
  /** v-label -> the reference images used and the title, for the "generated" message. */
  info: Record<string, VariantInfo>;
};

export type VariantInfo = { refs: string[]; title?: string };

export const LABEL_RE = /\[([av]\d+)\]/g;

/**
 * Work out which images a generate_image prompt will use, exactly as the tool does:
 * images attached in this turn that the prompt does not mention are added in front (if enabled),
 * then every label in the prompt, in order of first appearance.
 */
export function resolveRefs(prompt: string, media: MediaState, autoAttach: boolean) {
  let autoAdded: string[] = [];
  if (autoAttach) {
    autoAdded = media.turnAttachments.filter(
      l => media.attachments[l] && !new RegExp(`\\[${l}\\]`).test(prompt),
    );
    if (autoAdded.length) {
      const list = autoAdded.map(l => `[${l}]`).join(" and ");
      prompt = `Using ${list} as reference image${autoAdded.length > 1 ? "s" : ""}: ${prompt}`;
    }
  }
  const labels: string[] = [];
  for (const m of prompt.matchAll(LABEL_RE)) {
    if (!labels.includes(m[1])) labels.push(m[1]);
  }
  return { prompt, labels, autoAdded };
}

export const tags = (labels: string[]) => labels.map(l => `[${l}]`).join("");

const STATE_FILE = "comfy_media.json";

export function mediaDir(ctl: { getWorkingDirectory(): string }): string {
  try {
    return ctl.getWorkingDirectory();
  } catch {
    // No working directory (e.g. used outside a chat). Fall back to a shared temp folder.
    return join(tmpdir(), "lmstudio-comfy-chat");
  }
}

export async function loadMedia(dir: string): Promise<MediaState> {
  try {
    const parsed = JSON.parse(await readFile(join(dir, STATE_FILE), "utf-8"));
    return {
      attachments: parsed.attachments ?? {},
      variants: parsed.variants ?? {},
      turnAttachments: parsed.turnAttachments ?? [],
      info: parsed.info ?? {},
    };
  } catch {
    return { attachments: {}, variants: {}, turnAttachments: [], info: {} };
  }
}

export async function saveMedia(dir: string, state: MediaState): Promise<void> {
  await mkdir(dir, { recursive: true });
  await writeFile(join(dir, STATE_FILE), JSON.stringify(state, null, 2), "utf-8");
}

/** Marker the tool puts in its result so the generator knows which variants to show the model. */
export const RESULT_MARKER_RE = /\(comfy-gen:\s*([^)]*)\)/;

export function parseResultMarker(content: string): string[] {
  const m = RESULT_MARKER_RE.exec(content);
  if (!m) return [];
  return m[1]
    .split(",")
    .map(s => s.trim())
    .filter(s => /^v\d+$/.test(s));
}
